const animals = [
  'fly',
  'spider',
  'bird',
  'cat',
  'dog',
  'goat',
  'cow',
  'horse'
];

const sayings = [
  '',
  'It wriggled and jiggled and tickled inside her.',
  'How absurd to swallow a bird!',
  'Imagine that, to swallow a cat!',
  'What a hog, to swallow a dog!',
  'Just opened her throat and swallowed a goat!',
  'I don\'t know how she swallowed a cow!',
  "She's dead, of course!"
];

const verse = (n: number): string => {
  const index = n - 1;
  const lines: string[] = [];

  lines.push(`I know an old lady who swallowed a ${animals[index]}.`);

  if (index > 0) {
    lines.push(sayings[index]);
  }

  for (let i = index; i > 0; i--) {
    lines.push(`She swallowed the ${animals[i]} to catch the ${animals[i - 1]}`);
    if (i - 1 === 1) {
      lines.push('that wriggled and jiggled and tickled inside her');
    }
  }

  lines.push('I don\'t know why she swallowed the fly. Perhaps she\'ll die.');

  if (index === 7) {
    lines[lines.length - 1] = "She's dead, of course!";
  }

  return lines.join('\n') + '\n';
};

export const verse: VerseFn = (n) => {
  return verse(n);
};

